class CsvError(Exception):
    def __init__(self, line, col):
        self.line = line
        self.col = col
        super().__init__(f"CSV error at line {line}, column {col}")


def parse(text: str, dialect: dict) -> list:
    if text.startswith('\ufeff'):
        text = text[1:]
    n = len(text)
    if n == 0:
        return []

    delimiter = dialect.get('delimiter', ',')
    quote = dialect.get('quote', '"')
    escape = dialect.get('escape', None)
    skip_initial_space = dialect.get('skip_initial_space', False)
    comment = dialect.get('comment', None)
    skip_blank = dialect.get('skip_blank', True)
    strict = dialect.get('strict', True)
    header = dialect.get('header', False)
    fill = dialect.get('fill', None)
    null_values = dialect.get('null_values', [])
    if null_values is None:
        null_values = []
    infer_ints = dialect.get('infer_ints', False)
    trim = dialect.get('trim', False)
    null_set = set(null_values)

    def make_positions():
        line_at = [1] * n
        col_at = [1] * n
        line = 1
        col = 1
        i = 0
        while i < n:
            line_at[i] = line
            col_at[i] = col
            ch = text[i]
            if ch == '\r':
                if i + 1 < n and text[i + 1] == '\n':
                    line_at[i + 1] = line
                    col_at[i + 1] = col + 1
                    line += 1
                    col = 1
                    i += 2
                else:
                    line += 1
                    col = 1
                    i += 1
            elif ch == '\n':
                line += 1
                col = 1
                i += 1
            else:
                col += 1
                i += 1
        return line_at, col_at

    if quote is not None:
        line_at, col_at = make_positions()
    else:
        line_at = []
        col_at = []

    def is_break(i):
        if i >= n:
            return False
        c = text[i]
        return c == '\n' or c == '\r'

    def break_len(i):
        if text[i] == '\r' and i + 1 < n and text[i + 1] == '\n':
            return 2
        return 1

    def postprocess(s):
        if trim:
            s = s.strip(' \t')
        if s in null_set:
            return None
        if infer_ints:
            if s:
                start = 1 if s[0] == '-' else 0
                if start < len(s):
                    ok = True
                    for j in range(start, len(s)):
                        c = s[j]
                        if c < '0' or c > '9':
                            ok = False
                            break
                    if ok:
                        return int(s)
        return s

    def make_header(fields):
        names = []
        counts = {}
        for idx, name in enumerate(fields, 1):
            base = name
            if base == '':
                base = f'col{idx}'
            k = counts.get(base, 0)
            if k:
                name = f'{base}_{k + 1}'
            else:
                name = base
            counts[base] = k + 1
            names.append(name)
        return names

    header_names = None
    results = []

    def make_dict(record):
        d = {}
        for name, value in zip(header_names, record):
            d[name] = value
        if len(record) < len(header_names):
            for name in header_names[len(record):]:
                d[name] = fill
        elif len(record) > len(header_names):
            d['_extra'] = record[len(header_names):]
        return d

    def add_record(record):
        nonlocal header_names
        if header:
            if header_names is None:
                header_names = make_header(record)
            else:
                results.append(make_dict(record))
        else:
            results.append(record)

    i = 0
    while True:
        if i >= n:
            break

        if is_break(i):
            if not skip_blank:
                current_is_header = header and header_names is None
                value = '' if current_is_header else postprocess('')
                add_record([value])
            i += break_len(i)
            continue

        if comment is not None and text[i] == comment:
            while i < n and not is_break(i):
                i += 1
            if i < n:
                i += break_len(i)
            continue

        current_is_header = header and header_names is None
        record = []

        while True:
            if skip_initial_space:
                while i < n and text[i] == ' ':
                    i += 1

            if quote is not None and i < n and text[i] == quote:
                start_quote = i
                i += 1
                parts = []

                while True:
                    if i >= n:
                        raise CsvError(line_at[start_quote], col_at[start_quote])

                    ch = text[i]

                    if escape is not None and ch == escape:
                        if i + 1 >= n:
                            raise CsvError(line_at[start_quote], col_at[start_quote])
                        parts.append(text[i + 1])
                        i += 2
                        continue

                    if ch == quote:
                        if escape is None and i + 1 < n and text[i + 1] == quote:
                            parts.append(quote)
                            i += 2
                        else:
                            i += 1
                            break
                    else:
                        if ch == '\r' and i + 1 < n and text[i + 1] == '\n':
                            parts.append('\r\n')
                            i += 2
                        else:
                            parts.append(ch)
                            i += 1

                base = ''.join(parts)

                if i < n:
                    if text[i] == delimiter:
                        record.append(base)
                        i += 1
                        continue
                    if is_break(i):
                        record.append(base)
                        i += break_len(i)
                        break

                    if strict:
                        raise CsvError(line_at[i], col_at[i])

                    tail_start = i
                    while i < n and text[i] != delimiter and not is_break(i):
                        i += 1
                    value = base + text[tail_start:i]

                    if i < n:
                        if text[i] == delimiter:
                            record.append(value)
                            i += 1
                            continue
                        if is_break(i):
                            record.append(value)
                            i += break_len(i)
                            break
                    else:
                        record.append(value)
                        break
                else:
                    record.append(base)
                    break

            else:
                start = i
                while i < n and text[i] != delimiter and not is_break(i):
                    i += 1
                field_text = text[start:i]
                value = field_text if current_is_header else postprocess(field_text)
                record.append(value)

                if i < n:
                    if text[i] == delimiter:
                        i += 1
                        continue
                    if is_break(i):
                        i += break_len(i)
                        break
                else:
                    break

        add_record(record)

    return results
